import React, { useState, useEffect } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Navbar = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearchFocused, setIsSearchFocused] = useState(false);
  const { user, logout, cart } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  // ✅ Автозаполнение поиска при загрузке из URL
  useEffect(() => {
    if (location.pathname === '/catalog') {
      const searchParams = new URLSearchParams(location.search);
      const searchQuery = searchParams.get('search');
      if (searchQuery) {
        setSearchTerm(searchQuery);
      }
    }
  }, [location]);

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchTerm.trim()) {
      navigate(`/catalog?search=${encodeURIComponent(searchTerm.trim())}`);
    } else {
      navigate('/catalog');
    }
    setIsSearchFocused(false);
  };

  const handleSearchChange = (e) => {
    setSearchTerm(e.target.value);
  };

  const clearSearch = () => {
    setSearchTerm('');
    if (location.pathname === '/catalog') {
      navigate('/catalog');
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      handleSearch(e);
    } else if (e.key === 'Escape') {
      setIsSearchFocused(false);
    }
  };

  // ✅ Функции для перехода на конкретные вкладки профиля
  const goToProfileTab = (tab) => {
    if (tab === 'profile') {
      navigate('/profile');
    } else {
      navigate(`/profile?tab=${tab}`);
    }
  };

  // ✅ Функция для выхода
  const handleLogout = () => {
    logout();
    navigate('/');
  };

  return (
    <nav className="bg-white shadow-lg border-b">
      <div className="max-w-7xl mx-auto px-4">
        <div className="flex justify-between items-center h-16">
          {/* Logo */}
          <Link to="/" className="flex items-center">
            <img src="./images/logo.png" alt="LUNA AUREA" className="h-8" />
            <span className="ml-2 text-xl font-serif font-bold">LUNA AUREA</span>
          </Link>

          {/* Navigation Links */}
          <div className="hidden md:flex space-x-8">
            <Link to="/catalog" className="text-gray-700 hover:text-gold-600">КАТАЛОГ</Link>
            <Link to="/catalog" className="text-gray-700 hover:text-gold-600">КОЛЛЕКЦИИ</Link>
            <Link to="/about" className="text-gray-700 hover:text-gold-600">О НАС</Link>
            <Link to="/contacts" className="text-gray-700 hover:text-gold-600">КОНТАКТЫ</Link>
          </div>

          {/* Icons */}
          <div className="flex items-center space-x-4">
            {/* Search - Улучшенная версия */}
            <div className="relative">
              <form onSubmit={handleSearch} className="relative">
                <input
                  type="text"
                  placeholder="Поиск товаров..."
                  value={searchTerm}
                  onChange={handleSearchChange}
                  onKeyDown={handleKeyPress}
                  onFocus={() => setIsSearchFocused(true)}
                  onBlur={() => setTimeout(() => setIsSearchFocused(false), 200)}
                  className="pl-4 pr-10 py-2 border border-gray-300 rounded-full text-sm focus:outline-none focus:ring-2 focus:ring-gold-500 focus:border-gold-500 w-64 transition-all"
                />
                <div className="absolute right-2 top-1/2 transform -translate-y-1/2 flex space-x-1">
                  {searchTerm && (
                    <button
                      type="button"
                      onClick={clearSearch}
                      className="text-gray-400 hover:text-gray-600 p-1"
                    >
                      ✕
                    </button>
                  )}
                  <button
                    type="submit"
                    className="text-gray-400 hover:text-gold-600 p-1 transition-colors"
                  >
                    🔍
                  </button>
                </div>
              </form>

              {/* Подсказки при фокусе (опционально) */}
              {isSearchFocused && (
                <div className="absolute top-full left-0 right-0 bg-white border border-gray-200 rounded-lg shadow-lg mt-2 z-50">
                  <div className="p-3 text-sm text-gray-500">
                    <div className="mb-2">💡 Попробуйте найти:</div>
                    <div className="space-y-1">
                      <div 
                        className="cursor-pointer hover:bg-gray-50 p-2 rounded"
                        onClick={() => setSearchTerm('кольцо')}
                      >
                        "кольцо", "серьги", "браслет"
                      </div>
                      <div 
                        className="cursor-pointer hover:bg-gray-50 p-2 rounded"
                        onClick={() => setSearchTerm('серебро')}
                      >
                        "серебро", "золото"
                      </div>
                      <div 
                        className="cursor-pointer hover:bg-gray-50 p-2 rounded"
                        onClick={() => setSearchTerm('luna')}
                      >
                        "luna", "solaris"
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Profile */}
            {user ? (
              <div className="relative group">
                <button className="p-2 hover:bg-gray-100 rounded-full">
                  👤
                </button>
                {/* Dropdown Menu */}
                <div className="absolute right-0 mt-2 w-48 bg-white rounded-md shadow-lg py-1 z-50 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200">
                  <button
                    onClick={() => navigate('/profile')}
                    className="block w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100"
                  >
                    Мой профиль
                  </button>
                  <button
                    onClick={() => goToProfileTab('orders')}
                    className="block w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100"
                  >
                    Мои заказы
                  </button>
                  <button
                    onClick={handleLogout}
                    className="block w-full text-left px-4 py-2 text-sm text-red-600 hover:bg-gray-100"
                  >
                    Выйти
                  </button>
                </div>
              </div>
            ) : (
              <Link to="/auth" className="p-2 hover:bg-gray-100 rounded-full">
                👤
              </Link>
            )}

            {/* Favorites */}
            <button 
              onClick={() => user ? goToProfileTab('favorites') : navigate('/auth')}
              className="p-2 hover:bg-gray-100 rounded-full"
            >
              ❤️
            </button>

            {/* Cart */}
            <button 
              onClick={() => user ? goToProfileTab('cart') : navigate('/auth')}
              className="p-2 hover:bg-gray-100 rounded-full relative"
            >
              🛒
              {user && cart && cart.length > 0 && (
                <span className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-5 h-5 text-xs flex items-center justify-center">
                  {cart.length}
                </span>
              )}
            </button>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
